<node CREATED="1794814745990" ID="ID_49723245" MODIFIED="1794814914111" TEXT="Databastyper">
<node CREATED="1794814923706" ID="ID_735589598" MODIFIED="1794814931583" POSITION="right" TEXT="Relationsdatabaser">
<node CREATED="1794815015210" ID="ID_1007728368" MODIFIED="1794815020400" TEXT="Lagrar data enligt en specifik struktur, i rader i tabeller d&#xe4;r varje tabell har en s&#xe4;rskild upps&#xe4;ttning kolumner."/>
<node CREATED="1794815022716" ID="ID_615512610" MODIFIED="1794815034863" TEXT="Representerar relationer mellan data p&#xe5; ett tydligt och effektivt s&#xe4;tt."/>
<node CREATED="1794815035293" ID="ID_1351638969" MODIFIED="1794815047211" TEXT="M&#xf6;jligt att st&#xe4;lla komplexa fr&#xe5;gor om datan."/>
<node CREATED="1794815047435" ID="ID_1190142494" MODIFIED="1794815057743" TEXT="L&#xe4;mpliga f&#xf6;r strukturerad data."/>
<node CREATED="1794815058820" ID="ID_602999714" MODIFIED="1794815069793" TEXT="Mindre l&#xe4;mpliga om man inte fr&#xe5;n b&#xf6;rjan vet exakt vilken typ av data som ska lagras, eftersom det &#xe4;r omst&#xe4;ndigt att uppdatera databasstrukturen."/>
</node>
<node CREATED="1794814934000" ID="ID_378636823" MODIFIED="1794814942681" POSITION="right" TEXT="NoSQL-databaser">
<node CREATED="1794815099331" ID="ID_32726317" MODIFIED="1794815164047" TEXT="Key&#x2013;value-databaser">
<node CREATED="1794815177949" ID="ID_1311726542" MODIFIED="1794815192340" TEXT="Enkel struktur med nycklar som &#xe4;r kopplade till v&#xe4;rden."/>
<node CREATED="1794815192529" ID="ID_323929102" MODIFIED="1794815201862" TEXT="L&#xe4;mpliga n&#xe4;r man bara beh&#xf6;ver kolla upp enstaka v&#xe4;rden och inte beh&#xf6;ver g&#xf6;ra mer komplexa fr&#xe5;gor som ber&#xf6;r olika relaterade data."/>
</node>
<node CREATED="1794815104597" ID="ID_1771624808" MODIFIED="1794815161072" TEXT="Dokumentdatabaser">
<node CREATED="1794815208536" ID="ID_840546864" MODIFIED="1794815218553" TEXT="Data lagras som dokument i olika samlingar. Alla dokument i en samling beh&#xf6;ver inte f&#xf6;lja samma struktur."/>
<node CREATED="1794815220909" ID="ID_1328200696" MODIFIED="1794815231012" TEXT="L&#xe4;mplig f&#xf6;r ostrukturerad data."/>
<node CREATED="1794815231220" ID="ID_1187817798" MODIFIED="1794815240126" TEXT="Flexibla eftersom alla dokument inte beh&#xf6;ver ha samma struktur, och man inte beh&#xf6;ver veta i f&#xf6;rv&#xe4;g exakt vilken typ av data som ska lagras."/>
<node CREATED="1794815240336" ID="ID_1506152125" MODIFIED="1794815325091" TEXT="Ist&#xe4;llet f&#xf6;r att ha relationer mellan olika dokument &#xe4;r det vanligt att lagra den relaterade information direkt inuti dokumentet eller som ett n&#xe4;stlat underdokument.."/>
<node CREATED="1794815273785" ID="ID_1124219715" MODIFIED="1794815284237" TEXT="Kan st&#xf6;dja avancerade fr&#xe5;gespr&#xe5;k liknande SQL, men vid komplexa fr&#xe5;gor kan de vara l&#xe5;ngsammare &#xe4;n f&#xf6;r relationsdatabaser."/>
</node>
<node CREATED="1794815118569" ID="ID_737076490" MODIFIED="1794815131761" TEXT="Kolumndatabaser">
<node CREATED="1794815356012" ID="ID_1029160101" MODIFIED="1794815358795" TEXT="Har en struktur med rader och kolumner liknande relationsdatabaser, men lagrar datan p&#xe5; ett s&#xe4;tt s&#xe5; att det &#xe4;r snabbare att komma &#xe5;t kolumner &#xe4;n rader."/>
<node CREATED="1794815359172" ID="ID_886089155" MODIFIED="1794815399752" TEXT="I vissa fall &#xe4;r strukturen friare &#xe4;n i relationsdatabaser, med m&#xf6;jlighet att ha olika upps&#xe4;ttningar av kolumner f&#xf6;r olika rader."/>
<node CREATED="1794815399953" ID="ID_493116917" MODIFIED="1794815411250" TEXT="&#xc4;r snabba n&#xe4;r man beh&#xf6;ver analysera alla v&#xe4;rden i en viss kolumn."/>
</node>
<node CREATED="1794815132007" ID="ID_500984102" MODIFIED="1794815158646" TEXT="Grafdatabaser">
<node CREATED="1794815427678" ID="ID_484146783" MODIFIED="1794815429485" TEXT="Datan &#xe4;r ordnad som noder i en graf, med kopplingar mellan noderna."/>
<node CREATED="1794815429691" ID="ID_776102060" MODIFIED="1794815439087" TEXT="Kopplingarna representerar samband mellan datan."/>
<node CREATED="1794815439299" ID="ID_840484980" MODIFIED="1794815453951" TEXT="L&#xe4;mpliga n&#xe4;r sambanden mellan data &#xe4;r av prim&#xe4;r betydelse."/>
</node>
</node>
<node CREATED="1794814943978" ID="ID_1534102322" MODIFIED="1794814955970" POSITION="right" TEXT="NewSQL-databaser">
<node CREATED="1794815468445" ID="ID_1580675050" MODIFIED="1794815469860" TEXT="Anv&#xe4;nder samma datamodell som relationsdatabaser och st&#xf6;der SQL som fr&#xe5;gespr&#xe5;k."/>
<node CREATED="1794815470070" ID="ID_90276587" MODIFIED="1794815515032" TEXT="&#xc4;r internt uppbyggda annorlunda &#xe4;n traditionella relationsdatabaser, p&#xe5; ett s&#xe4;tt som g&#xf6;r att prestandan enklare kan skalas upp s&#xe5; att de kan hantera st&#xf6;rre datam&#xe4;ngder snabbare."/>
</node>
</node>
</map>
